      category = 'building',
      usage = 'get_room(zone, id) / find_actor(keyword) / wait(seconds) / wait_hours(n)',
      source_file = 'data/help/lua-world.md',
      updated_at = now()
    WHERE id = v_id
      AND (keywords, title, content, min_level, category, usage, source_file)
          IS DISTINCT FROM (ARRAY['lua-world', 'world', 'lua globals', 'globals', 'lua functions']::text[], 'Lua API: World and Global Functions', $help$Globals every trigger can use (return type after ->). Wherever (zone, id) is
